<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api,session}from'../api';const settings=reactive({wecom_webhook:'',enabled_types:['system_blocked','device_offline','studio_crashed'],minimum_severity:'critical',quiet_start:'',quiet_end:''}),configured=ref(false),saving=ref(false),message=ref('');async function load(){const x=await api('/tk-api/enterprise/alert-settings');Object.assign(settings,x.settings||{});configured.value=x.wecom_configured;}async function save(){saving.value=true;message.value='';try{const x=await api('/tk-api/enterprise/alert-settings',{method:'POST',body:JSON.stringify(settings)});configured.value=x.wecom_configured;settings.wecom_webhook='';message.value='告警配置已加密保存';}catch(e:any){message.value=e.message}finally{saving.value=false}}onMounted(load);</script>
<template><div class="page-stack"><section class="subscription-hero"><div><span class="eyebrow light">ENTERPRISE SUBSCRIPTION</span><h2>{{session.subscription?.plan_code||'企业版'}}</h2><p>按设备额度管理企业名下的开播电脑</p></div><div><span>设备额度</span><strong>{{session.subscription?.device_limit||'-'}}</strong><small>到期 {{session.subscription?.expires_at?.slice(0,10)||'未设置'}}</small></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">ALERT DELIVERY</span><h2>企业微信告警</h2><p>Webhook密钥只在服务端加密保存，页面不会回显原始地址。</p></div><span class="status-pill" :class="configured?'true':'false'"><i></i>{{configured?'已配置':'未配置'}}</span></header><form class="settings-form" @submit.prevent="save"><label>企业微信群机器人 Webhook<input v-model="settings.wecom_webhook" type="password" placeholder="https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=..."></label><label>最低告警级别<select v-model="settings.minimum_severity"><option value="critical">仅严重告警</option><option value="warning">警告及以上</option></select></label><label>静默开始<input v-model="settings.quiet_start" type="time"></label><label>静默结束<input v-model="settings.quiet_end" type="time"></label><button class="primary" :disabled="saving">{{saving?'正在保存…':'保存告警配置'}}</button><span class="form-message">{{message}}</span></form></section></div></template>
